import { ActionMetrics, SimResult, SimResultFilter } from '../../proto_utils/sim_result.js';
import { bucket } from '../../utils.js';

import { playerDamageBarScale } from './metrics_bar_helpers.js';
import { MetricsCombinedTooltipTable } from './metrics_combined_tooltip_table.js';
import { ColumnSortType, MetricsTable } from './metrics_table.js';
import { MetricsTotalBar } from './metrics_total_bar.js';
import { ResultComponent, ResultComponentConfig, SimResultData } from './result_component.js';

// Attaches a threat breakdown tooltip, hidden unless threat metrics are enabled.
const threatTooltip = (metric: ActionMetrics, cellElem: HTMLElement, value: number) => {
	if (!value) return;
	MetricsCombinedTooltipTable({
		tooltipElement: cellElem,
		headerValues: [undefined, 'Amount'],
		hasMetricBars: false,
		tooltipConfig: {
			onShow: () => (document.querySelector('.hide-threat-metrics') ? false : undefined),
		},
		groups: [
			{
				spellSchool: metric.spellSchool,
				totalPercentage: 100,
				data: [{ name: 'Threat', value, percentage: 100 }],
			},
		],
	});
};

// Single combined damage table (melee + spell + pets) with Cataclysm-style clean
// columns; the detailed outcome/threat breakdowns live in hover tooltips.
export class DamageMetricsTable extends MetricsTable<ActionMetrics> {
	private maxValue = 0;
	private totalValue = 0;

	constructor(config: ResultComponentConfig) {
		config.rootCssClass = 'damage-metrics-root';

		config.resultsEmitter.on((_, resultData) => {
			const scale = resultData ? playerDamageBarScale(resultData) : { max: 0, total: 0 };
			this.maxValue = scale.max;
			this.totalValue = scale.total;
		});

		super(config, [
			MetricsTable.nameCellConfig((metric: ActionMetrics) => {
				return {
					name: metric.name,
					actionId: metric.actionId,
				};
			}),
			{
				name: 'Damage done',
				tooltip: 'Total Damage Done',
				headerCellClass: 'metrics-table-cell--primary-metric',
				columnClass: 'metrics-table-cell--primary-metric',
				getValue: (metric: ActionMetrics) => metric.damage,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => {
					cellElem.appendChild(
						MetricsTotalBar({
							spellSchool: metric.spellSchool,
							percentage: this.totalValue > 0 ? (metric.damage / this.totalValue) * 100 : 0,
							max: this.maxValue,
							total: metric.damage,
							value: metric.damage,
						}),
					);
				},
			},
			{
				name: 'Casts',
				tooltip: 'Casts',
				getValue: (metric: ActionMetrics) => metric.casts,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => {
					cellElem.textContent = metric.casts.toFixed(1);
					const landed = metric.landedHits || metric.casts;
					MetricsCombinedTooltipTable({
						tooltipElement: cellElem,
						groups: [
							{
								spellSchool: metric.spellSchool,
								totalPercentage: 100,
								data: [
									{ name: 'Hits', value: landed, percentage: 100 - metric.missPercent - metric.dodgePercent - metric.parryPercent },
									{ name: 'Miss', value: metric.misses, percentage: metric.missPercent },
									{ name: 'Dodge', value: metric.dodges, percentage: metric.dodgePercent },
									{ name: 'Parry', value: metric.parries, percentage: metric.parryPercent },
								],
							},
						],
					});
				},
			},
			{
				name: 'Avg Cast',
				tooltip: 'Damage / Casts',
				getValue: (metric: ActionMetrics) => metric.avgCast,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => {
					cellElem.textContent = metric.avgCast.toFixed(1);
					threatTooltip(metric, cellElem, metric.avgCastThreat);
				},
			},
			{
				name: 'Hits',
				tooltip: 'Hits + Crits + Glances + Blocks',
				getValue: (metric: ActionMetrics) => metric.landedHits,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => {
					cellElem.textContent = metric.landedHits.toFixed(1);
					const landed = metric.landedHits || 1;
					MetricsCombinedTooltipTable({
						tooltipElement: cellElem,
						groups: [
							{
								spellSchool: metric.spellSchool,
								totalPercentage: 100,
								data: [
									{ name: 'Hit', value: metric.hits, percentage: (metric.hits / landed) * 100 },
									{ name: 'Critical Hit', value: metric.crits, percentage: (metric.crits / landed) * 100 },
									{ name: 'Glancing Blow', value: metric.glances, percentage: (metric.glances / landed) * 100 },
									{ name: 'Blocked Hit', value: metric.blocks, percentage: (metric.blocks / landed) * 100 },
								],
							},
						],
					});
				},
			},
			{
				name: 'Avg Hit',
				tooltip: 'Damage / (Hits + Crits + Glances + Blocks)',
				getValue: (metric: ActionMetrics) => metric.avgHit,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => {
					cellElem.textContent = metric.avgHit.toFixed(1);
					threatTooltip(metric, cellElem, metric.avgHitThreat);
				},
			},
			{
				name: 'Crit %',
				tooltip: 'Crits / Swings',
				getValue: (metric: ActionMetrics) => metric.critPercent,
				getDisplayString: (metric: ActionMetrics) => metric.critPercent.toFixed(2) + '%',
			},
			{
				name: 'Miss %',
				tooltip: 'Misses / Swings',
				getValue: (metric: ActionMetrics) => metric.missPercent + metric.dodgePercent + metric.parryPercent,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => {
					const totalMiss = metric.missPercent + metric.dodgePercent + metric.parryPercent;
					cellElem.textContent = totalMiss.toFixed(2) + '%';
					MetricsCombinedTooltipTable({
						tooltipElement: cellElem,
						groups: [
							{
								spellSchool: metric.spellSchool,
								totalPercentage: 100,
								data: [
									{ name: 'Miss', value: metric.misses, percentage: metric.missPercent },
									{ name: 'Dodge', value: metric.dodges, percentage: metric.dodgePercent },
									{ name: 'Parry', value: metric.parries, percentage: metric.parryPercent },
								],
							},
						],
					});
				},
			},
			{
				name: 'DPET',
				tooltip: 'Damage / Avg Cast Time',
				getValue: (metric: ActionMetrics) => metric.dpet,
				getDisplayString: (metric: ActionMetrics) => metric.dpet.toFixed(1),
			},
			{
				name: 'TPS',
				tooltip: 'Threat / Encounter Duration',
				columnClass: 'threat-metrics',
				getValue: (metric: ActionMetrics) => metric.tps,
				getDisplayString: (metric: ActionMetrics) => metric.tps.toFixed(1),
			},
			{
				name: 'DPS',
				tooltip: 'Damage / Encounter Duration',
				headerCellClass: 'text-body',
				sort: ColumnSortType.Descending,
				getValue: (metric: ActionMetrics) => metric.dps,
				fillCell: (metric: ActionMetrics, cellElem: HTMLElement) => {
					const span = document.createElement('span');
					span.classList.add('text-success');
					span.textContent = metric.dps.toFixed(1);
					cellElem.appendChild(span);
					threatTooltip(metric, cellElem, metric.tps);
				},
			},
		]);
	}

	customizeRowElem(action: ActionMetrics, rowElem: HTMLElement) {
		if (action.hitAttempts == 0 && action.dps == 0) {
			rowElem.classList.add('threat-metrics');
		}
	}

	getGroupedMetrics(resultData: SimResultData): Array<Array<ActionMetrics>> {
		const players = resultData.result.getPlayers(resultData.filter);
		if (players.length != 1) {
			return [];
		}
		const player = players[0];

		// Combine melee + spell into a single list, grouped by action id.
		const actions = [...player.getMeleeActions(), ...player.getSpellActions()].map(action => action.forTarget(resultData.filter));
		const actionGroups = ActionMetrics.groupById(actions);

		const petsByName = bucket(player.pets, pet => pet.name);
		const petGroups = Object.values(petsByName).map(pets =>
			ActionMetrics.joinById(
				pets.flatMap(pet => [...pet.getMeleeActions(), ...pet.getSpellActions()].map(action => action.forTarget(resultData.filter))),
				true,
			),
		);

		return actionGroups.concat(petGroups);
	}

	mergeMetrics(metrics: Array<ActionMetrics>): ActionMetrics {
		return ActionMetrics.merge(metrics, true, metrics[0].unit?.petActionId || undefined);
	}

	shouldCollapse(metric: ActionMetrics): boolean {
		return !metric.unit?.isPet;
	}
}
