import { element, fragment, ref } from 'tsx-vanilla';
// @ts-expect-error
import debounce from 'lodash/debounce';

import { SimLog } from '../../proto_utils/logs_parser.js';
import { TypedEvent } from '../../typed_event.js';
import { BaseModal } from '../base_modal.js';
import { BooleanPicker } from '../boolean_picker.js';
import { CopyButton } from '../copy_button.js';
import { ResultComponent, ResultComponentConfig, SimResultData } from './result_component.js';

export class LogRunner extends ResultComponent {
	private virtualScroll: CustomVirtualScroll | null = null;
	private showDebug = false;
	private filteredLogs: SimLog[] = [];
	private ui: {
		search: HTMLInputElement;
		actions: HTMLDivElement;
		// still WIP
		// buttonToTop: HTMLButtonElement;
		scrollContainer: HTMLDivElement;
		contentContainer: HTMLTableSectionElement;
	};
	cacheOutput: {
		resultData: SimResultData | null;
		logs: SimLog[] | null;
		logsAsHTML: Element[] | null;
		logsAsText: string[] | null;
	} = { resultData: null, logs: null, logsAsHTML: null, logsAsText: null };

	readonly showDebugChangeEmitter = new TypedEvent<void>('Show Debug');

	constructor(config: ResultComponentConfig) {
		config.rootCssClass = 'log-runner-root';
		super(config);

		const searchRef = ref<HTMLInputElement>();
		const actionsRef = ref<HTMLDivElement>();
		const exportAllRef = ref<HTMLButtonElement>();
		const exportFilteredRef = ref<HTMLButtonElement>();
		// const buttonToTopRef = ref<HTMLButtonElement>();
		const scrollContainerRef = ref<HTMLDivElement>();
		const contentContainerRef = ref<HTMLTableSectionElement>();

		this.rootElem.appendChild(
			<>
				<div ref={actionsRef} className="log-runner-actions">
					<input ref={searchRef} type="text" className="form-control log-search-input" placeholder="Filter logs" />
					<button ref={exportAllRef} className="btn btn-primary log-runner-export-btn" title="Download every log line, ignoring the filter">
						<i className="fa fa-download me-1"></i>
						Export Log
					</button>
					<button ref={exportFilteredRef} className="btn btn-outline-primary log-runner-export-btn" title="Download only the lines matching the current filter">
						<i className="fa fa-filter me-1"></i>
						Export Filtered
					</button>
					{/* <button ref={buttonToTopRef} className="btn btn-primary order-last log-runner-scroll-to-top-btn">
						Top
					</button> */}
				</div>
				<div ref={scrollContainerRef} className="log-runner-scroll">
					<table className="metrics-table log-runner-table">
						<thead>
							<tr className="metrics-table-header-row">
								<th>Time</th>
								<th>
									<div className="d-flex align-items-end">Event</div>
								</th>
							</tr>
						</thead>
						<tbody ref={contentContainerRef} className="log-runner-logs"></tbody>
					</table>
				</div>
			</>,
		);

		this.ui = {
			search: searchRef.value!,
			actions: actionsRef.value!,
			// buttonToTop: buttonToTopRef.value!,
			scrollContainer: scrollContainerRef.value!,
			contentContainer: contentContainerRef.value!,
		};

		// Use the 'input' event to trigger search as the user types
		const onSearchHandler = () => {
			this.searchLogs(this.ui.search.value);
		};
		this.ui.search?.addEventListener('input', debounce(onSearchHandler, 150));
		exportAllRef.value!.addEventListener('click', () => this.exportLogs(this.cacheOutput.logs ?? [], 'Export Log'));
		exportFilteredRef.value!.addEventListener('click', () => {
			// Flush the debounced search so the export matches what is typed right now.
			onSearchHandler();
			this.exportLogs(this.filteredLogs, 'Export Filtered Log');
		});
		// this.ui.buttonToTop?.addEventListener('click', () => {
		// 	this.virtualScroll?.scrollToTop();
		// });

		new BooleanPicker<LogRunner>(this.ui.actions, this, {
			extraCssClasses: ['show-debug-picker'],
			label: 'Show Debug Statements',
			inline: true,
			reverse: true,
			changedEvent: () => this.showDebugChangeEmitter,
			getValue: () => this.showDebug,
			setValue: (eventID, _logRunner, newValue) => {
				this.showDebug = newValue;
				this.showDebugChangeEmitter.emit(eventID);
			},
		});

		this.showDebugChangeEmitter.on(() => {
			onSearchHandler();
		});
		this.initializeClusterize();
	}

	private initializeClusterize(): void {
		this.virtualScroll = new CustomVirtualScroll({
			scrollContainer: this.ui.scrollContainer,
			contentContainer: this.ui.contentContainer,
			itemHeight: 32,
		});
	}

	searchLogs(searchQuery: string): void {
		// Regular expression to match quoted phrases or words
		const matchQuotesRegex = /"([^"]+)"|\S+/g;
		let match;
		const keywords: any[] = [];
		// Extract keywords and quoted phrases from the search query
		while ((match = matchQuotesRegex.exec(searchQuery))) {
			keywords.push(match[1] ? match[1].toLowerCase() : match[0].toLowerCase());
		}
		if (!this.cacheOutput.logsAsHTML) return;

		const filteredIndexes: number[] = [];
		this.cacheOutput.logsAsText!.forEach((logText, index) => {
			const logRaw = this.cacheOutput.logs![index].raw;

			if (!this.showDebug && logRaw.match(/.*\[DEBUG\].*/)) return;

			const matches = keywords.every(keyword => {
				if (keyword.startsWith('"') && keyword.endsWith('"')) {
					// Remove quotes for exact phrase match
					return logText.includes(keyword.slice(1, -1));
				}
				return logText.includes(keyword);
			});
			if (matches) filteredIndexes.push(index);
		});

		this.filteredLogs = filteredIndexes.map(index => this.cacheOutput.logs![index]);
		this.virtualScroll?.setItems(filteredIndexes.map(index => this.cacheOutput.logsAsHTML![index]));
	}

	// One line per log, "mm:ss:mmm;event", matching the newer sims' export format.
	private exportLogs(logs: SimLog[], title: string): void {
		const text = logs.map(log => `${log.formattedTimestamp()};${log.raw.replace(/^\[-?[0-9.]+\]\s*/, '')}`).join('\n');
		new LogExporter(document.body, title, text);
	}

	onSimResult(resultData: SimResultData): void {
		this.getLogs(resultData);
		this.searchLogs(this.ui.search.value);
	}

	getLogs(resultData: SimResultData) {
		if (!resultData) return [];
		if (this.cacheOutput.resultData === resultData) {
			return this.cacheOutput.logsAsHTML;
		}

		const validLogs = resultData.result.logs.filter(log => !log.isCastCompleted());
		this.cacheOutput.resultData = resultData;
		this.cacheOutput.logs = validLogs;
		this.cacheOutput.logsAsHTML = validLogs.map(log => this.renderItem(log));
		this.cacheOutput.logsAsText = this.cacheOutput.logsAsHTML.map(element => (element.textContent || '').trim().toLowerCase());
	}

	renderItem(log: SimLog) {
		return (
			<tr>
				<td className="log-timestamp">{log.formattedTimestamp()}</td>
				<td className="log-event">{this.getLogHtml(log)}</td>
			</tr>
		) as HTMLTableRowElement;
	}

	private getLogHtml(log: SimLog): Element {
		if ((log as any).toHTML) {
			return (log as any).toHTML(false).cloneNode(true);
		}
		const eventString = log.toString(false).trim();
		const wrapper = <span></span>;
		wrapper.innerHTML = eventString;
		return wrapper;
	}
}

// Same dialog as the sim's other exporters (textarea + Copy + Download), but without needing a SimUI,
// since the detailed results can run in their own tab.
class LogExporter extends BaseModal {
	constructor(parent: HTMLElement, title: string, text: string) {
		super(parent, 'exporter', { title, footer: true });

		const textareaRef = ref<HTMLTextAreaElement>();
		this.body.appendChild(<textarea ref={textareaRef} spellcheck={false} readOnly className="exporter-textarea form-control"></textarea>);
		const textarea = textareaRef.value!;
		textarea.value = text;

		new CopyButton(this.footer!, {
			extraCssClasses: ['btn-primary', 'me-2'],
			getContent: () => textarea.value,
			text: 'Copy',
			tooltip: 'Copy to clipboard',
		});

		const downloadBtnRef = ref<HTMLButtonElement>();
		this.footer!.appendChild(
			<button ref={downloadBtnRef} className="exporter-button btn btn-primary download-button">
				<i className="fa fa-download me-1"></i>
				Download
			</button>,
		);
		downloadBtnRef.value!.addEventListener('click', () => {
			// A Blob URL rather than downloadString's data URI: full logs run to many MB.
			const url = URL.createObjectURL(new Blob([textarea.value], { type: 'text/csv;charset=utf-8' }));
			const anchor = document.createElement('a');
			anchor.href = url;
			anchor.download = 'wowsims-log.csv';
			document.body.appendChild(anchor); // required for firefox
			anchor.click();
			anchor.remove();
			setTimeout(() => URL.revokeObjectURL(url), 0);
		});
	}
}

class CustomVirtualScroll {
	private scrollContainer: HTMLElement;
	private contentContainer: HTMLElement;
	private items: Element[];
	private itemHeight: number;
	private visibleItemsCount: number;
	private startIndex: number;
	private placeholderTop: HTMLElement;
	private placeholderBottom: HTMLElement;

	constructor({ scrollContainer, contentContainer, itemHeight }: { scrollContainer: HTMLElement; contentContainer: HTMLElement; itemHeight: number }) {
		this.scrollContainer = scrollContainer;
		this.contentContainer = contentContainer;
		this.items = [];
		this.itemHeight = itemHeight;
		this.visibleItemsCount = 100; // +1 for buffer
		this.startIndex = 0;

		this.placeholderTop = document.createElement('tr');
		this.placeholderTop.innerHTML = '<td colspan="2"></td>';
		this.placeholderBottom = document.createElement('tr');
		this.placeholderBottom.innerHTML = '<td colspan="2"></td>';
		contentContainer.prepend(this.placeholderTop);
		contentContainer.append(this.placeholderBottom);

		this.attachScrollListener();
	}

	scrollToTop(): void {
		this.scrollContainer.scrollTop = 0;
		this.startIndex = 0; // Reset startIndex to ensure items are updated correctly
		this.updateVisibleItems(); // Update the visible items after scrolling to top
	}

	setItems(newItems: CustomVirtualScroll['items']): void {
		// Adjust the type of newItems as needed
		this.items = newItems;
		this.scrollToTop();
	}

	private attachScrollListener(): void {
		const onScroll = () => {
			if (!this.scrollContainer.isConnected) {
				window.removeEventListener('scroll', onScroll, { capture: true });
				this.scrollContainer.removeEventListener('scroll', onScroll);
				return;
			}

			let scrollTop = this.scrollContainer.scrollTop;
			if (scrollTop == 0) {
				const rect = this.scrollContainer.getBoundingClientRect();
				if (rect.top < 0) {
					scrollTop = Math.abs(rect.top);
				}
			}

			const newIndex = Math.floor(scrollTop / this.itemHeight);
			if (newIndex !== this.startIndex) {
				this.startIndex = newIndex;
				this.updateVisibleItems();
			}
		};
		this.scrollContainer.addEventListener('scroll', onScroll);
		window.addEventListener('scroll', onScroll, { capture: true });
	}

	private updateVisibleItems(): void {
		const endIndex = this.startIndex + this.visibleItemsCount;
		const visibleItems = this.items.slice(this.startIndex, endIndex);
		const remainingItems = Math.max(0, this.items.length - endIndex);

		// Update the height of the placeholders before it's placed in the dom to prevent rerender
		this.placeholderTop.innerHTML = `<td colspan="2" style="height: ${this.startIndex * this.itemHeight}px; border: none; margin: 0; padding: 0;"></td>`;
		this.placeholderBottom.innerHTML = `<td colspan="2" style="height: ${remainingItems * this.itemHeight}px; border: none; margin: 0; padding: 0;"></td>`;
		this.contentContainer.replaceChildren(
			<>
				{this.placeholderTop}
				{visibleItems.map(item => item)}
				{this.placeholderBottom}
			</>,
		);
	}
}